CREATE POLICY "community media readable" ON storage.objects FOR SELECT USING (bucket_id = 'community-media');
CREATE POLICY "members upload community media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'community-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "members update own community media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'community-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "members delete own community media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'community-media' AND (storage.foldername(name))[1] = auth.uid()::text);